  html[data-theme="light"] .punch-chip--danger { background: rgba(220,38,38,0.08) !important; border-color: rgba(220,38,38,0.24) !important; color: #b91c1c !important; }

  /* ── Light Mode — Wave 2: ItemDetail screen ── */
