  html[data-theme="light"] .sp-filter-trigger.is-active { color: #4a2a86; }

  html[data-theme="light"] .sp-table thead { background: rgba(61,67,76,0.045); }
  html[data-theme="light"] .sp-table td { border-bottom-color: rgba(61,67,76,0.1); }
  html[data-theme="light"] .sp-table tbody tr:hover { background: rgba(61,67,76,0.035); }
  html[data-theme="light"] .sp-table tbody tr.is-selected { background: rgba(104,52,179,0.07); }

  html[data-theme="light"] .sp-menu { background: rgba(255,255,255,0.98); }
