  /* ── Typography utilities ── */
  .sp-page-title    { font-size:clamp(24px,2vw,32px); line-height:1.2; font-weight:800; letter-spacing:normal; color:var(--sp-text-primary); }
  [dir="ltr"] .sp-page-title { letter-spacing:-0.025em; }
  .sp-section-title { font-size:18px; line-height:1.4; font-weight:700; color:var(--sp-text-primary); }
  .sp-card-title    { font-size:15px; line-height:1.4; font-weight:700; color:var(--sp-text-primary); }
  .sp-body          { font-size:14px; line-height:1.65; font-weight:400; color:var(--sp-text-secondary); }
  .sp-label         { font-size:12px; line-height:1.4; font-weight:600; color:var(--sp-text-secondary); }
  .sp-caption       { font-size:12px; line-height:1.5; font-weight:400; color:var(--sp-text-muted); }

  /* ── Buttons ──
     Wave 2.1 button rule (app-wide, single source of truth here so every
     .sp-button consumer inherits it automatically): primary = solid gold
     fill + dark text, secondary = transparent/ivory surface + border,
     ghost = textual only (no box), danger = red + distinct. No gradients,
     no glow, radius 6-8px, minimum 44px touch target. ── */
  .sp-button { --button-height:44px; min-height:var(--button-height); display:inline-flex; align-items:center; justify-content:center; gap:9px; padding-inline:16px; border-radius:8px; border:1px solid transparent; font-family:inherit; font-size:14px; line-height:1; font-weight:700; white-space:nowrap; cursor:pointer; user-select:none; transition: transform var(--sp-duration-fast) var(--sp-ease-standard), background var(--sp-duration-normal) var(--sp-ease-standard), border-color var(--sp-duration-normal) var(--sp-ease-standard), color var(--sp-duration-normal) var(--sp-ease-standard), filter var(--sp-duration-normal) var(--sp-ease-standard); }
  .sp-button:hover:not(:disabled)  { transform: translateY(-1px); }
  .sp-button:active:not(:disabled) { transform: translateY(0) scale(0.985); }
  .sp-button:focus-visible { outline:3px solid rgba(79,95,231,0.28); outline-offset:2px; }
  .sp-button:disabled { opacity:0.46; cursor:not-allowed; }
  .sp-button--primary { color:#1a1200; background:var(--gold); border-color:var(--gold-end); box-shadow:none; }
  .sp-button--primary:hover:not(:disabled) { filter:brightness(1.08); border-color:var(--gold-end); }
  .sp-button--secondary { color:var(--sp-text-primary); background:rgba(255,255,255,0.055); border-color:var(--sp-border-default); box-shadow:none; }
  .sp-button--secondary:hover:not(:disabled) { background:rgba(255,255,255,0.085); border-color:var(--sp-border-strong); }
  .sp-button--ghost { color:var(--sp-text-secondary); background:transparent; border-color:transparent; }
  .sp-button--ghost:hover:not(:disabled) { color:var(--sp-text-primary); background:rgba(255,255,255,0.05); }
  /* Return navigation remains a clear control without the bright, heavy frame
     that made project headers read like warning banners. */
  .sp-button.sp-button--back { min-height:44px; max-width:100%; min-width:0; padding:10px 15px; white-space:normal; overflow-wrap:anywhere; line-height:1.4; text-align:start; color:var(--sp-back-ink); background:var(--sp-back-bg); border:1px solid var(--sp-back-border); box-shadow:inset 0 1px 0 rgba(255,255,255,0.035); }
  .sp-button.sp-button--back:hover:not(:disabled) { color:var(--sp-back-ink); background:var(--sp-back-hover); border-color:var(--sp-back-border); }
  .sp-button.sp-button--back:active:not(:disabled) { background:var(--sp-back-hover); }
  .sp-button.sp-button--back:focus-visible { outline:3px solid var(--sp-primary-border); outline-offset:3px; }
  .sp-button--gold { color:#f6df98; background:var(--sp-gold-soft); border-color:var(--sp-gold-border); box-shadow:none; }
  .sp-button--gold:hover:not(:disabled) { color:#ffe9a9; background:rgba(212,175,71,0.15); border-color:rgba(212,175,71,0.44); }
  .sp-button--danger { color:#ffd8dc; background:var(--sp-danger-soft); border-color:rgba(239,91,103,0.34); }
  .sp-button--danger:hover:not(:disabled) { color:#fff; background:rgba(239,91,103,0.19); border-color:rgba(239,91,103,0.5); }
  .sp-icon-button { width:44px; height:44px; display:inline-grid; place-items:center; padding:0; border-radius:8px; color:var(--sp-text-secondary); background:rgba(255,255,255,0.045); border:1px solid var(--sp-border-subtle); cursor:pointer; transition: color var(--sp-duration-normal), background var(--sp-duration-normal), border-color var(--sp-duration-normal), transform var(--sp-duration-fast); }
  .sp-icon-button:hover { color:var(--sp-text-primary); background:rgba(255,255,255,0.075); border-color:var(--sp-border-default); }
  .sp-icon-button:active { transform:scale(0.96); }

  /* ── Surfaces ── */
  .sp-panel { background:linear-gradient(180deg,rgba(17,24,39,0.9),rgba(12,18,30,0.92)); border:1px solid var(--sp-border-subtle); border-radius:var(--sp-radius-xl); box-shadow:var(--sp-shadow-sm), inset 0 1px 0 rgba(255,255,255,0.035); }
  .sp-card { background:rgba(18,27,44,0.74); border:1px solid var(--sp-border-subtle); border-radius:var(--sp-radius-lg); box-shadow:inset 0 1px 0 rgba(255,255,255,0.025); }
  .sp-card--interactive { transition: transform var(--sp-duration-normal) var(--sp-ease-standard), border-color var(--sp-duration-normal), background var(--sp-duration-normal), box-shadow var(--sp-duration-normal); }
  .sp-card--interactive:hover { transform:translateY(-2px); background:rgba(22,32,51,0.82); border-color:var(--sp-border-default); box-shadow:var(--sp-shadow-sm); }

  /* ── Inputs ── */
  .sp-field { display:flex; flex-direction:column; gap:7px; min-width:0; max-width:100%; }
  .sp-input, .sp-select, .sp-textarea { width:100%; min-width:0; max-width:100%; min-height:44px; padding:0 13px; color:var(--sp-text-primary); caret-color:var(--sp-primary-hover); background:rgba(7,11,19,0.48); border:1px solid var(--sp-border-default); border-radius:11px; outline:none; font-family:inherit; font-size:14px; transition: background var(--sp-duration-normal), border-color var(--sp-duration-normal), box-shadow var(--sp-duration-normal); }
  /* WebKit 301648: padded native date/time controls exceed width:100% on iOS.
     Remove padding only there, including legacy fields with inline styles. */
  @supports (-webkit-touch-callout: none) {
    @media (pointer:coarse) {
      input[type="date"], input[type="datetime-local"], input[type="time"], input[type="month"], input[type="week"] { padding:0 !important; }
    }
  }
  .sp-textarea { min-height:110px; padding-block:12px; resize:vertical; }
  .sp-input::placeholder, .sp-textarea::placeholder { color:var(--sp-text-disabled); }
  .sp-input:hover, .sp-select:hover, .sp-textarea:hover { border-color:var(--sp-border-strong); background:rgba(9,14,24,0.62); }
  .sp-input:focus, .sp-select:focus, .sp-textarea:focus { border-color:var(--sp-primary-border); background:rgba(10,15,25,0.8); box-shadow:0 0 0 3px rgba(79,95,231,0.12), inset 0 1px 0 rgba(255,255,255,0.025); }
  .sp-input.is-invalid, .sp-select.is-invalid, .sp-textarea.is-invalid { border-color:rgba(239,91,103,0.6); }

  /* iOS Safari and installed PWAs auto-zoom focused controls below 16px and
     can retain that visual viewport after navigation. Keep every mobile
     keyboard-producing control at the accessible no-zoom threshold. */
  @media (max-width: 900px) and (pointer: coarse) {
    input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="color"]):not([type="file"]):not([type="button"]):not([type="submit"]):not([type="reset"]),
    select,
    textarea { font-size:16px !important; }
  }

  /* ── Segmented control ── */
  .sp-segmented { display:grid; grid-auto-flow:column; grid-auto-columns:minmax(0,1fr); gap:6px; padding:5px; background:rgba(6,10,17,0.42); border:1px solid var(--sp-border-subtle); border-radius:13px; }
  .sp-segmented__item { min-height:38px; border:1px solid transparent; border-radius:9px; color:var(--sp-text-muted); background:transparent; font:inherit; font-size:13px; font-weight:600; cursor:pointer; transition: color var(--sp-duration-normal), background var(--sp-duration-normal), border-color var(--sp-duration-normal), box-shadow var(--sp-duration-normal); }
  .sp-segmented__item:hover { color:var(--sp-text-secondary); background:rgba(255,255,255,0.035); }
  .sp-segmented__item.is-active { color:var(--sp-text-primary); background:rgba(255,255,255,0.065); border-color:var(--sp-border-default); box-shadow:var(--sp-shadow-xs); }

  /* ── Filters ── */
  .sp-filter-bar { display:flex; align-items:center; flex-wrap:wrap; gap:10px; padding:12px; background:rgba(14,21,34,0.62); border:1px solid var(--sp-border-subtle); border-radius:var(--sp-radius-lg); }
  .sp-filter-trigger { min-height:38px; display:inline-flex; align-items:center; gap:8px; padding-inline:12px; color:var(--sp-text-secondary); background:rgba(255,255,255,0.035); border:1px solid var(--sp-border-subtle); border-radius:10px; cursor:pointer; }
  .sp-filter-trigger.is-active { color:#d9ddff; background:var(--sp-primary-soft); border-color:var(--sp-primary-border); }

  /* ── Table ── */
  .sp-table-shell { overflow:hidden; background:rgba(13,19,32,0.78); border:1px solid var(--sp-border-subtle); border-radius:var(--sp-radius-lg); box-shadow:var(--sp-shadow-sm); }
  .sp-table thead { background:rgba(255,255,255,0.025); }
  .sp-table th { height:46px; padding:0 14px; color:var(--sp-text-muted); font-size:12px; font-weight:700; text-align:start; border-bottom:1px solid var(--sp-border-subtle); }
  .sp-table td { padding:11px 14px; color:var(--sp-text-secondary); border-bottom:1px solid rgba(255,255,255,0.045); }
  .sp-table tbody tr { transition: background var(--sp-duration-normal), box-shadow var(--sp-duration-normal); }
  .sp-table tbody tr:hover { background:rgba(255,255,255,0.028); }
  .sp-table tbody tr.is-selected { background:rgba(79,95,231,0.08); box-shadow:inset 3px 0 0 var(--sp-primary); }

  /* ── Badges ── */
  .sp-badge { min-height:24px; display:inline-flex; align-items:center; gap:6px; padding-inline:9px; border-radius:var(--sp-radius-pill); border:1px solid transparent; font-size:12px; font-weight:700; }
  .sp-badge--success { color:#6fe3a8; background:var(--sp-success-soft); border-color:rgba(39,199,122,0.24); }
  .sp-badge--warning { color:#ffd265; background:var(--sp-warning-soft); border-color:rgba(243,185,56,0.25); }
  .sp-badge--danger  { color:#ff8c96; background:var(--sp-danger-soft);  border-color:rgba(239,91,103,0.26); }
  .sp-badge--info    { color:#82c8ff; background:var(--sp-info-soft);     border-color:rgba(73,167,242,0.25); }
  .sp-badge--primary { color:#bfc6ff; background:var(--sp-primary-soft);  border-color:rgba(79,95,231,0.28); }

  /* ── Menu / Modal / Toast / Media ── */
  .sp-menu { min-width:210px; padding:7px; background:rgba(14,21,34,0.96); border:1px solid var(--sp-border-default); border-radius:14px; box-shadow:var(--sp-shadow-lg); backdrop-filter:blur(22px); }
  .sp-menu-item { min-height:40px; display:flex; align-items:center; gap:10px; padding-inline:11px; border-radius:9px; color:var(--sp-text-secondary); cursor:pointer; }
  .sp-menu-item:hover { color:var(--sp-text-primary); background:rgba(255,255,255,0.055); }
  .sp-menu-item.is-selected { color:#d7dbff; background:var(--sp-primary-soft); }
  .sp-modal-backdrop { position:fixed; inset:0; background:rgba(2,5,10,0.72); backdrop-filter:blur(8px); -webkit-backdrop-filter:blur(8px); }
  .pdf-preview-screen { position:fixed; inset:0; background:var(--sp-bg-canvas); backdrop-filter:none; -webkit-backdrop-filter:none; }
  .sp-dialog { width:min(1120px, calc(100vw - 40px)); max-height:calc(100vh - 40px); overflow:auto; background:linear-gradient(180deg,rgba(17,25,41,0.97),rgba(10,15,25,0.98)); border:1px solid var(--sp-border-default); border-radius:22px; box-shadow:0 36px 120px rgba(0,0,0,0.68), inset 0 1px 0 rgba(255,255,255,0.05); }
  .sp-dialog__header { position:sticky; top:0; z-index:3; min-height:68px; display:flex; align-items:center; justify-content:space-between; padding:14px 18px; background:rgba(13,19,32,0.91); border-bottom:1px solid var(--sp-border-subtle); backdrop-filter:blur(18px); }
  .sp-dialog__footer { position:sticky; bottom:0; z-index:3; display:flex; justify-content:flex-start; gap:10px; padding:14px 18px; background:rgba(13,19,32,0.93); border-top:1px solid var(--sp-border-subtle); backdrop-filter:blur(18px); }
  /* Operations sheets deliberately own one internal scroll region. The
     workspace underneath is locked while a sheet is open, so a phone never
     gets a second full-height page moving behind the active workflow. */
  .sp-operations-sheet-backdrop { position:fixed; inset:0; z-index:1200; display:flex; align-items:center; justify-content:flex-end; min-height:0; padding:12px; background:rgba(0,0,0,.56); overscroll-behavior:contain; }
  [dir="rtl"] .sp-operations-sheet-backdrop { justify-content:flex-start; }
  .sp-operations-sheet { width:min(100%,680px); max-height:calc(100vh - 24px); max-height:calc(100dvh - 24px); min-height:0; display:flex; flex-direction:column; overflow:hidden; color:var(--sp-text-primary); background:var(--sp-app-bg); border:1px solid var(--sp-border-default); border-radius:var(--sp-radius-lg); box-shadow:var(--sp-shadow-lg); }
  .sp-operations-sheet__header { flex:0 0 auto; min-height:64px; display:flex; align-items:flex-start; justify-content:space-between; gap:12px; padding:12px 16px; background:var(--sp-glass-bg-strong); border-bottom:1px solid var(--sp-border-subtle); backdrop-filter:blur(18px); -webkit-backdrop-filter:blur(18px); }
  .sp-operations-sheet__header h2 { margin:0; font-size:20px; line-height:1.3; }
  .sp-operations-sheet__body { flex:1 1 auto; min-height:0; overflow-y:auto; overflow-x:hidden; overscroll-behavior-y:contain; -webkit-overflow-scrolling:touch; padding:14px 16px 24px; }
  .sp-operations-sheet__notice { flex:0 0 auto; margin:8px 12px 0 !important; }
  .sp-operations-sheet__footer { flex:0 0 auto; display:flex; flex-wrap:wrap; gap:8px; padding:12px 16px calc(12px + env(safe-area-inset-bottom)); background:var(--sp-glass-bg-strong); border-top:1px solid var(--sp-border-subtle); backdrop-filter:blur(18px); -webkit-backdrop-filter:blur(18px); }
  .sp-operations-sheet .sp-operations-sheet__footer { margin-top:0; }
  .sp-operations-sheet__footer .sp-button { flex:1 1 150px; }
  @media (max-width:760px) {
    .sp-operations-sheet-backdrop { align-items:flex-end; justify-content:center; padding:0; }
    [dir="rtl"] .sp-operations-sheet-backdrop { justify-content:center; }
    .sp-operations-sheet { width:100%; max-height:92vh; max-height:92dvh; border-radius:var(--sp-radius-lg) var(--sp-radius-lg) 0 0; border-bottom:0; }
    .sp-operations-sheet__header { min-height:58px; padding:10px 12px; }
    .sp-operations-sheet__body { padding:12px 12px 20px; }
    .sp-operations-sheet__footer { padding:10px 12px calc(10px + env(safe-area-inset-bottom)); }
  }
  @media (max-height:560px) {
    .sp-operations-sheet { max-height:96vh; max-height:96dvh; }
    .sp-operations-sheet__header { min-height:50px; padding-block:7px; }
    .sp-operations-sheet__body { padding-block:9px 14px; }
  }
  .sp-toast { width:min(380px, calc(100vw - 28px)); display:grid; grid-template-columns:auto minmax(0,1fr) auto; align-items:start; gap:11px; padding:13px 14px; background:rgba(15,23,38,0.94); border:1px solid var(--sp-border-default); border-radius:14px; box-shadow:var(--sp-shadow-lg); backdrop-filter:blur(20px); }
  .sp-media-dropzone { position:relative; min-height:280px; display:grid; place-items:center; padding:26px; text-align:center; background:radial-gradient(420px 180px at 50% 40%, rgba(79,95,231,0.1), transparent 70%), rgba(7,11,19,0.38); border:1px dashed rgba(150,163,190,0.25); border-radius:var(--sp-radius-lg); overflow:hidden; transition: border-color var(--sp-duration-normal), background var(--sp-duration-normal), box-shadow var(--sp-duration-normal); }
  .sp-media-dropzone:hover, .sp-media-dropzone.is-dragging { border-color:rgba(99,113,238,0.58); background:radial-gradient(420px 180px at 50% 40%, rgba(79,95,231,0.16), transparent 70%), rgba(9,14,24,0.54); box-shadow:0 0 0 4px rgba(79,95,231,0.07); }
  .sp-camera-orb { width:78px; height:78px; display:grid; place-items:center; margin-inline:auto; border-radius:24px; color:#c9ceff; background:linear-gradient(145deg,rgba(109,120,239,0.22),rgba(43,53,114,0.14)); border:1px solid rgba(135,145,255,0.28); box-shadow:0 14px 32px rgba(33,43,108,0.26), inset 0 1px 0 rgba(255,255,255,0.1); }

  /* ── Desktop navigation rail (docs/DESKTOP_NAVIGATION_SHELL_SPEC.md) ──
     Operations: in-flow rail inside .sp-dshell. Punch edition: the same rail,
     fixed at inline-start (.sp-sidebar), with .sp-shell-pad following its width.
     Below 1024px the shell wrappers are display:contents and no rail shows.
     No backdrop-filter on the rail: it would trap the fixed collapsed flyout. */
  .sp-dshell, .sp-dshell__content { display: contents; }
  .sp-sidebar, .sp-punch-tabs { display: none; }
  .sp-dnav { --sp-dnav-width: 248px; flex-direction: column; gap: 8px; width: var(--sp-dnav-width); padding: 12px 10px; padding-top: calc(12px + env(safe-area-inset-top)); background: var(--sp-glass-bg-strong); border-inline-end: 1px solid var(--sp-border-subtle); color: var(--sp-text-secondary); font-family: var(--sp-font-ui); transition: width var(--sp-duration-normal) var(--sp-ease-standard); }
  .sp-dnav.is-collapsed { --sp-dnav-width: 72px; padding-inline: 12px; }
  .sp-dnav__brand { display: flex; align-items: center; gap: 10px; min-height: 48px; padding: 4px 8px 12px; border-bottom: 1px solid var(--sp-border-subtle); }
  .sp-dnav__brand-mark { flex: 0 0 auto; width: 32px; height: 32px; border-radius: var(--sp-radius-xs); object-fit: contain; }
  .sp-dnav__brand-mark--tenant { width: auto; max-width: 100%; }
  .sp-dnav__brand-name { min-width: 0; font-size: 16px; font-weight: 800; letter-spacing: -0.01em; color: var(--sp-text-primary); overflow-wrap: anywhere; }
  .sp-dnav__scroll { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; gap: 10px; overflow-y: auto; overflow-x: hidden; overscroll-behavior: contain; }
  .sp-dnav__list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 2px; }
  .sp-dnav__list--modules { padding-top: 10px; border-top: 1px solid var(--sp-border-subtle); }
  .sp-dnav__footer { flex: 0 0 auto; padding-top: 8px; border-top: 1px solid var(--sp-border-subtle); }
  .sp-dnav__item, .sp-dnav__subitem { position: relative; width: 100%; min-height: 44px; display: flex; align-items: center; gap: 12px; padding: 8px 12px; border: 1px solid transparent; border-radius: var(--sp-radius-sm); background: transparent; color: var(--sp-text-secondary); font: inherit; font-size: 14px; font-weight: 600; line-height: 1.35; text-align: start; cursor: pointer; transition: background-color var(--sp-duration-fast) var(--sp-ease-standard), border-color var(--sp-duration-fast) var(--sp-ease-standard), color var(--sp-duration-fast) var(--sp-ease-standard); }
  .sp-dnav__subitem { gap: 10px; padding-inline: 10px; font-size: 13.5px; }
  .sp-dnav__item:hover, .sp-dnav__subitem:hover { color: var(--sp-text-primary); background: var(--sp-surface-hover); }
  .sp-dnav__item:focus-visible, .sp-dnav__subitem:focus-visible, .sp-punch-tabs__tab:focus-visible { outline: 2px solid var(--sp-primary-ink); outline-offset: 2px; }
  .sp-dnav__item:disabled { opacity: 0.5; cursor: not-allowed; }
  .sp-dnav__item.is-active, .sp-dnav__subitem[aria-current="page"] { color: var(--sp-primary-ink); background: var(--sp-primary-soft); border-color: var(--sp-primary-border); }
  .sp-dnav__item[aria-current="page"]::before, .sp-dnav__subitem[aria-current="page"]::before { content: ""; position: absolute; inset-inline-start: -1px; inset-block: 10px; width: 3px; border-radius: var(--sp-radius-pill); background: var(--sp-primary-ink); }
  .sp-dnav__module.is-active { background: transparent; border-color: transparent; color: var(--sp-text-primary); }
  .sp-dnav__module.is-active .sp-dnav__icon { color: var(--sp-primary-ink); }
  .sp-dnav__icon { flex: 0 0 20px; display: inline-flex; align-items: center; justify-content: center; }
  .sp-dnav__label, .sp-dnav__sublabel { flex: 1 1 auto; min-width: 0; overflow-wrap: anywhere; }
  .sp-dnav__chevron { flex: 0 0 auto; display: inline-flex; color: var(--sp-text-muted); transition: transform var(--sp-duration-fast) var(--sp-ease-standard); }
  .sp-dnav__module[aria-expanded="true"] .sp-dnav__chevron { transform: rotate(180deg); }
  .sp-dnav__submenu { margin-block: 2px 6px; padding-inline-start: 21px; }
  .sp-dnav__submenu[hidden] { display: none; }
  .sp-dnav__submenu-title { display: none; }
  .sp-dnav__sublist { list-style: none; margin: 0; padding: 0; padding-inline-start: 8px; border-inline-start: 1px solid var(--sp-border-subtle); display: flex; flex-direction: column; gap: 2px; }
  .sp-dnav.is-collapsed .sp-dnav__brand { justify-content: center; padding-inline: 0; }
  .sp-dnav.is-collapsed .sp-dnav__brand-mark--tenant { max-width: 44px; }
  .sp-dnav.is-collapsed .sp-dnav__item { justify-content: center; gap: 0; padding-inline: 0; }
  .sp-dnav.is-collapsed .sp-dnav__brand-name,
  .sp-dnav.is-collapsed .sp-dnav__item > .sp-dnav__label { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; }
  .sp-dnav.is-collapsed .sp-dnav__chevron { display: none; }
  .sp-dnav.is-collapsed .sp-dnav__module[aria-expanded="true"] { color: var(--sp-text-primary); background: var(--sp-surface-hover); border-color: var(--sp-border-default); }
  .sp-dnav.is-collapsed .sp-dnav__module.is-active { color: var(--sp-primary-ink); background: var(--sp-primary-soft); border-color: var(--sp-primary-border); }
  .sp-dnav.is-collapsed .sp-dnav__submenu { position: fixed; z-index: 70; inset-block: 0; inset-inline-start: var(--sp-dnav-width); width: min(288px, calc(100vw - var(--sp-dnav-width))); margin: 0; padding: 16px 12px; padding-top: calc(16px + env(safe-area-inset-top)); overflow-y: auto; overscroll-behavior: contain; background: var(--sp-surface-1); border-inline-end: 1px solid var(--sp-border-default); box-shadow: var(--sp-shadow-lg); }
  .sp-dnav.is-collapsed .sp-dnav__submenu-title { display: block; margin: 4px 10px 12px; font-size: 13px; font-weight: 800; line-height: 1.4; color: var(--sp-text-muted); overflow-wrap: anywhere; }
  .sp-dnav.is-collapsed .sp-dnav__sublist { padding-inline-start: 0; border-inline-start: 0; }
  .sp-punch-tabs { flex-shrink: 0; gap: 4px; padding-block: 8px; padding-inline: 20px; overflow-x: auto; border-bottom: 1px solid var(--sp-border-subtle); background: var(--sp-glass-bg); }
  .sp-punch-tabs__tab { min-height: 44px; display: inline-flex; align-items: center; gap: 8px; padding: 8px 14px; border: 1px solid transparent; border-radius: var(--sp-radius-sm); background: transparent; color: var(--sp-text-secondary); font: inherit; font-size: 14px; font-weight: 600; white-space: nowrap; cursor: pointer; }
  .sp-punch-tabs__tab:hover { color: var(--sp-text-primary); background: var(--sp-surface-hover); }
  .sp-punch-tabs__tab[aria-current="page"] { color: var(--sp-primary-ink); background: var(--sp-primary-soft); border-color: var(--sp-primary-border); }

  @media (min-width: 1024px) {
    .sp-sidebar { position: fixed; z-index: 90; inset-block: 0; inset-inline-start: 0; display: flex; }
    .sp-shell-pad { padding-inline-start: 248px; }
    .sp-shell-pad[data-dnav-collapsed="true"] { padding-inline-start: 72px; }
    .sp-dshell--active { flex: 1 1 auto; min-height: 0; height: 100%; display: flex; flex-direction: row; overflow: hidden; }
    .sp-dshell--active > .sp-dnav { position: relative; z-index: 60; display: flex; flex: 0 0 auto; height: 100%; }
    .sp-dshell--active > .sp-dshell__content { flex: 1 1 auto; min-width: 0; min-height: 0; height: 100%; display: flex; flex-direction: column; overflow: hidden; }
    .sp-dshell--active .sp-shell-pad { padding-inline-start: 0; }
    .sp-dshell--active .sp-punch-tabs { display: flex; }
    /* The rail already lists modules, settings and Project home. */
    .sp-dshell--active .ops-home[data-level="home"] .ops-tiles--modules,
    .sp-dshell--active .ops-home[data-level="home"] .ops-home__utilities,
    .sp-dshell--active .ops-home[data-level="home"] .ops-home__lead,
    .sp-dshell--active .ops-home__module-back { display: none; }
    .sp-mobile-only { display: none !important; }
    .sp-topbar-skin { background: var(--sp-glass-bg) !important; border-bottom-color: var(--sp-glass-border) !important; box-shadow: var(--sp-shadow-sm) !important; backdrop-filter: blur(20px) saturate(130%); -webkit-backdrop-filter: blur(20px) saturate(130%); }
  }

  /* ── PWA viewport resilience — height-based compact chrome ──────────────
     Every @media above is width-only; a resized desktop PWA window can get
     SHORT (not just narrow), and none of the width rules help with that —
     the fixed-height header/toolbar/BottomNav rows just eat the whole
     window, squeezing content to ~0px. These two breakpoints shrink the
     chrome itself (not the content, no transform:scale, no zoom lock) so
     flex:1 content areas actually reclaim real space. See
     PWA_VIEWPORT_RESILIENCE_SPEC.md. Critical actions (nav row 1: back,
     bell, theme, language) are untouched — only the secondary row 2
     (project name/status chips) and the toolbar/BottomNav padding shrink. */
  @media (max-height: 560px) {
    .sp-header-row1 { padding: 6px 14px 4px !important; }
    .sp-header-logo { height: 34px !important; }
    .sp-header-row2 { padding: 0 14px 5px !important; }
    .punch-list-toolbar { padding: 6px 14px !important; }
    .sp-bottom-nav { padding: 3px 10px !important; padding-bottom: calc(3px + env(safe-area-inset-bottom)) !important; }
    .sp-bottom-tab span { display: none; } /* icon-only tabs — still fully usable, just label-less */
    .sp-dialog__header { min-height: 46px !important; padding: 8px 16px !important; }
    .sp-dialog__footer { padding: 8px 16px !important; }
  }
  @media (max-height: 420px) {
    .sp-header-row2 .sp-status-chips { display: none; } /* status filters still reachable inside List/Settings — this row is the tightest squeeze */
    .sp-bottom-tab { padding: 4px 4px !important; }
  }


  /* ── Toast (components/ui/Feedback.jsx) ── */
  @keyframes sp-toast-in {
    from { opacity: 0; transform: translateY(10px) scale(0.98); }
    to   { opacity: 1; transform: translateY(0) scale(1); }
  }
  .sp-toast-item { animation: sp-toast-in 200ms var(--sp-ease-spring) both; }

  /* ── Motion ── */
  @keyframes sp-page-enter { from { opacity:0; transform:translateY(6px) scale(0.995); } to { opacity:1; transform:translateY(0) scale(1); } }
  .sp-page-enter { animation: sp-page-enter 220ms var(--sp-ease-spring) both; }
  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { scroll-behavior:auto !important; animation-duration:0.01ms !important; animation-iteration-count:1 !important; transition-duration:0.01ms !important; }
    /* חריג מכוון: ספינר הטעינה הוא פידבק פונקציונלי ("האפליקציה עדיין
       עובדת"), לא אנימציית קישוט — בלעדיו, הכלל הכללי למעלה קופא אותו
       אחרי 0.01ms ונראה כאילו האפליקציה תקועה במקום רק טוענת. */
    .sp-ring { animation-duration: 2.4s !important; animation-iteration-count: infinite !important; }
  }

.sp-project-header {
  background: linear-gradient(180deg, rgba(13,14,20,0.97) 0%, rgba(10,11,16,0.99) 100%);
  border-bottom: 1px solid rgba(212,175,55,0.18);
  flex-shrink: 0;
  position: relative;
  z-index: 50;
  box-shadow: 0 2px 18px rgba(0,0,0,0.6), 0 1px 0 rgba(212,175,55,0.1);
  padding-top: env(safe-area-inset-top);
  font-family: var(--sp-font-ui);
  text-align: start;
}

.sp-project-header--sticky { position: sticky; top: 0; }
.sp-project-header__row1 { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; gap: 8px; padding: 8px 14px 4px; }
.sp-project-header__back { min-height: 44px; border-radius: 8px; padding: 7px 12px; font: inherit; font-size: 13px; font-weight: 700; cursor: pointer; }
.sp-project-header__back-glyph { color: var(--sp-primary-ink); }
.sp-project-header__back { grid-column: 1; grid-row: 1; justify-self: start; max-width: 100%; overflow-wrap: anywhere; line-height: 1.35; }
.sp-project-header__logo-button { grid-column: 2; grid-row: 1; justify-self: center; margin: 0; min-width: 0; max-width: 100%; min-height: 44px; display: inline-flex; align-items: center; justify-content: center; }
.sp-project-header__back:disabled,
.sp-project-header__logo-button:disabled { opacity: 0.5; cursor: not-allowed; }
.sp-project-header__logo { display: block; width: auto; max-width: min(34vw, 200px); height: 66px; object-fit: contain; opacity: 0.98; }
.sp-project-header__actions { display: flex; align-items: center; justify-content: flex-end; gap: 6px; min-width: 0; flex: 0 0 auto; flex-wrap: nowrap; }
.sp-project-header__actions > button,
.sp-project-header__actions > * > button { min-width: 44px; min-height: 44px; box-sizing: border-box; flex-shrink: 0; border-radius: 10px !important; }
.sp-project-header__action { width: 44px; height: 44px; min-width: 44px; min-height: 44px; padding: 0; display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; background: var(--sp-surface-2); border: 1px solid var(--sp-border-subtle); border-radius: 10px; color: var(--sp-text-secondary); font: inherit; cursor: pointer; }
.sp-project-header__action:focus-visible { outline: 2px solid var(--sp-primary-ink); outline-offset: 3px; }
.sp-project-header__action:disabled { opacity: 0.5; cursor: not-allowed; }
.sp-project-header__row2 { display: flex; align-items: center; gap: 8px; padding: 0 14px 8px; flex-wrap: wrap; }
.sp-project-header__identity { flex: 1 1 120px; min-width: 0; }
.sp-project-header__project { font-size: 15px; line-height: 1.35; font-weight: 800; color: var(--sp-text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sp-project-header__meta { margin-top: 2px; font-size: 11px; line-height: 1.45; color: var(--sp-text-secondary); overflow-wrap: anywhere; }
.sp-project-header__trailing { display: flex; align-items: center; gap: 8px; min-width: 0; flex: 1 1 auto; flex-wrap: wrap; }

/* Keep the Operations masthead to two visual rows on phones: navigation +
   brand, then project identity beside its tools. PunchList can add its status
   strip as a dedicated third row without splitting the tools from identity. */
@media (max-width: 760px) {
  .sp-project-header__row1 { grid-template-columns: minmax(0, 1fr) minmax(0, 124px) minmax(0, 1fr); gap: 6px; padding-inline: 10px; }
  .sp-project-header__logo { max-width: 100%; height: 60px; }
  .sp-project-header .sp-project-header__row1 .sp-project-header__back { padding-inline: 7px; gap: 4px; font-size: 13px; }
  .sp-project-header__row2 { padding-inline: 10px; gap: 6px; flex-wrap: wrap; }
  .sp-project-header__identity { flex-basis: 64px; }
  .sp-project-header__actions { gap: 4px; }
  .sp-project-header__trailing { flex:1 0 100%; width:100%; overflow-x:auto; }
}

@media (max-height: 560px) {
  .sp-project-header__logo { height: 44px; }
}

/* Desktop navigation rail (docs/DESKTOP_NAVIGATION_SHELL_SPEC.md): the rail owns
   brand, level navigation, help and AI, so the masthead keeps identity + tools. */
@media (min-width: 1024px) {
  .sp-project-header--in-shell .sp-project-header__logo-button { display: none; }
  .sp-project-header--in-shell:not(.sp-project-header--keeps-back) .sp-project-header__row1 { display: none; }
  .sp-project-header--in-shell.sp-project-header--keeps-back .sp-project-header__row1 { display: flex; padding-block: 10px 0; padding-inline: 20px; }
  .sp-project-header--in-shell .sp-project-header__row2 { min-height: 64px; padding-block: 10px; padding-inline: 20px; gap: 12px; }
  .sp-project-header--in-shell .sp-project-header__action--rail { display: none; }
}


  .ops-home { height: 100%; min-height: 0; overflow: hidden; display: flex; flex-direction: column; background: var(--sp-app-bg); color: var(--sp-text-primary); font-family: var(--sp-font-ui); font-size: 1rem; }
  .ops-home__main { flex: 1; min-height: 0; width: 100%; max-width: 900px; margin-inline: auto; padding: clamp(16px, 4vw, 36px) clamp(12px, 4vw, 24px); padding-bottom: calc(32px + env(safe-area-inset-bottom)); overflow-y: auto; overflow-x: hidden; overscroll-behavior-y: contain; -webkit-overflow-scrolling: touch; }
  .ops-home__lead { margin: 10px 0 0; max-width: 58ch; font-size: clamp(16px, 1.6vw, 18px); line-height: 1.6; }
  .ops-home__utilities { margin-top: clamp(22px, 5vw, 34px); padding-top: 18px; border-top: 1px solid var(--sp-border-subtle); }
  .ops-home__utilities-title { margin: 0 0 12px; font-size: 15px; line-height: 1.4; font-weight: 800; color: var(--sp-text-secondary); }
  .ops-home__heading-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
  .ops-home__heading-row .sp-page-title { flex: 1 1 auto; min-width: 0; margin: 0; overflow-wrap: anywhere; }
  .ops-home__heading-action { margin-inline-start: auto; }
  .ops-home__identity-meta { display:flex; align-items:center; gap:5px; min-width:0; margin-top:3px; }
  .ops-home__number { color:var(--sp-text-muted); font-size:10px; white-space:nowrap; }
  .ops-home__role { display:inline-flex; align-items:center; max-width:100%; padding:2px 7px; border-radius:var(--sp-radius-xs); font-size:10px; line-height:1.35; font-weight:800; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
  .ops-tiles { display: grid; gap: 12px; margin-top: clamp(18px, 4vw, 26px); }
  .ops-tiles--modules { width: 100%; max-width: 740px; margin-inline: auto; grid-template-columns: repeat(auto-fit, minmax(min(248px, 100%), 1fr)); }
  .ops-tiles--activities { grid-template-columns: repeat(auto-fit, minmax(min(212px, 100%), 1fr)); }
  /* A status pill and a translated activity label cannot reliably share half
     of a phone screen. Keep activities one-per-row on mobile so long English,
     Russian and Arabic labels never collapse into a vertical word. */
  @media (max-width: 600px) { .ops-tiles--activities { grid-template-columns: minmax(0, 1fr); } }
  .ops-tile { display: flex; align-items: center; gap: 16px; width: 100%; min-height: 88px; padding: 18px; text-align: start; font: inherit; color: var(--sp-text-primary); cursor: pointer; }
  .ops-tiles--modules .ops-tile { min-height: 124px; padding: clamp(20px, 3vw, 26px); }
  .ops-tiles--activities .ops-tile { min-height: 104px; }
  .ops-tile__body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 6px; }
  .ops-tile__label { font-size: clamp(18px, 1.5vw, 20px); font-weight: 800; line-height: 1.3; overflow-wrap: anywhere; }
  .ops-tile__note { font-size: clamp(14px, 1.1vw, 15px); line-height: 1.55; color: var(--sp-text-secondary); overflow-wrap: anywhere; }
  .ops-tile__chevron { flex-shrink: 0; font-size: 24px; color: var(--sp-text-muted); }
  .ops-tile:focus-visible { outline: 3px solid var(--sp-primary-border); outline-offset: 2px; }
  .ops-tile--locked { cursor: default; }
  .ops-tile--locked .ops-tile__label { color: var(--sp-text-secondary); }
  .ops-tile__status { align-self: flex-start; flex-shrink: 0; padding: 4px 10px; border: 1px solid var(--sp-border-default); border-radius: var(--sp-radius-pill); background: var(--sp-surface-2); color: var(--sp-text-muted); font-size: 12px; font-weight: 700; white-space: nowrap; }
  @media (max-width: 420px) {
    .ops-home__number { display: none; }
    .ops-tiles--modules .ops-tile { min-height: 112px; padding: 18px; }
    .ops-tiles--activities .ops-tile { min-height: 96px; }
  }
  html[data-theme="light"] .ops-tile__status { background: rgba(61,67,76,0.06); border-color: rgba(61,67,76,0.2); }
